"""CSV dataset endpoints: upload, list, inspect, page through rows, delete."""

from __future__ import annotations

import logging
import re
import shutil
import uuid
from pathlib import Path
from typing import Annotated, Any

from fastapi import APIRouter, File, HTTPException, UploadFile

from app.config import get_settings
from app.core import ingest
from app.db import connection as db

log = logging.getLogger(__name__)

router = APIRouter(prefix="/datasets", tags=["datasets"])

MAX_PAGE = 500
DEFAULT_PAGE = 100

# Table names are generated by us (ds_<12 hex>), never user input, but this is
# the one place a name reaches SQL as an identifier rather than a bound value.
_TABLE_RE = re.compile(r"^ds_[0-9a-f]{12}$")


def _safe_table(name: str) -> str:
    if not _TABLE_RE.match(name or ""):
        raise HTTPException(500, f"refusing to query unexpected table name: {name!r}")
    return '"' + name + '"'


async def _dataset_or_404(dataset_id: str) -> dict[str, Any]:
    row = await db.run(db.query_one, "SELECT * FROM dataset WHERE id = ?", (dataset_id,))
    if not row:
        raise HTTPException(404, "dataset not found")
    return row


@router.get("")
async def list_datasets() -> list[dict]:
    return await db.run(
        db.query,
        "SELECT d.id, d.name, d.original_name, d.role, d.row_count, d.byte_size,"
        "       d.delimiter, d.encoding, d.status, d.error, d.created_at,"
        "       d.duplicate_rows, d.near_duplicate_rows, d.exclude_duplicates,"
        "       (SELECT COUNT(*) FROM dataset_column c WHERE c.dataset_id = d.id)"
        "         AS column_count"
        " FROM dataset d ORDER BY d.created_at ASC, d.rowid ASC",
    )


@router.post("/upload")
async def upload(files: Annotated[list[UploadFile], File()]) -> dict[str, Any]:
    """Ingest one or more CSVs. Each file is independent -- one bad file does
    not sink the rest, it comes back in `failed` with its reason."""
    settings = get_settings()
    created: list[dict[str, Any]] = []
    failed: list[dict[str, str]] = []

    for upload_file in files:
        original = upload_file.filename or "upload.csv"
        stem = Path(original).stem or "dataset"
        # Keep the raw file: re-ingest and audit both need the original bytes.
        stored = settings.upload_dir / f"{uuid.uuid4().hex[:12]}_{Path(original).name}"

        try:
            with stored.open("wb") as out:
                shutil.copyfileobj(upload_file.file, out)

            result = await db.run(
                ingest.ingest_csv, stored, name=stem, original_name=original
            )
            created.append(result)
        except ingest.IngestError as exc:
            failed.append({"file": original, "error": str(exc)})
            stored.unlink(missing_ok=True)
        except Exception as exc:
            log.exception("upload failed for %s", original)
            failed.append({"file": original, "error": f"{type(exc).__name__}: {exc}"})
            stored.unlink(missing_ok=True)
        finally:
            await upload_file.close()

    if not created and failed:
        raise HTTPException(400, {"message": "all uploads failed", "failed": failed})

    return {"created": created, "failed": failed}


@router.get("/{dataset_id}")
async def get_dataset(dataset_id: str) -> dict[str, Any]:
    row = await _dataset_or_404(dataset_id)
    columns = await db.run(
        db.query,
        "SELECT ordinal, source_name, column_name, inferred_type, null_count, sample"
        " FROM dataset_column WHERE dataset_id = ? ORDER BY ordinal",
        (dataset_id,),
    )
    return {**row, "columns": columns}


@router.post("/{dataset_id}/duplicates")
async def set_duplicate_policy(dataset_id: str, body: dict[str, Any]) -> dict[str, Any]:
    """Say whether this file's repeated rows are artefacts or findings.

    A per-dataset decision because it is a claim about the file, not about the
    system: only someone who knows how the export is produced can say that a
    repeated line means the exporter ran twice rather than that the money moved
    twice. Left off, duplicates are marked and still counted.
    """
    await _dataset_or_404(dataset_id)
    exclude = 1 if body.get("exclude") else 0
    await db.run(
        db.execute,
        "UPDATE dataset SET exclude_duplicates = ? WHERE id = ?",
        (exclude, dataset_id),
    )
    row = await _dataset_or_404(dataset_id)
    return {
        "dataset_id": dataset_id,
        "exclude_duplicates": bool(exclude),
        "duplicate_rows": row["duplicate_rows"],
        "near_duplicate_rows": row["near_duplicate_rows"],
        # Nothing is re-matched here. The existing proposals were built under
        # the old policy and saying so is better than silently leaving them.
        "note": "run the reconciliation again for this to take effect",
    }


@router.get("/{dataset_id}/rows")
async def get_rows(dataset_id: str, offset: int = 0, limit: int = DEFAULT_PAGE) -> dict[str, Any]:
    row = await _dataset_or_404(dataset_id)
    table = _safe_table(row["table_name"])

    offset = max(0, offset)
    limit = max(1, min(limit, MAX_PAGE))

    columns = await db.run(
        db.query,
        "SELECT ordinal, source_name, column_name, inferred_type"
        " FROM dataset_column WHERE dataset_id = ? ORDER BY ordinal",
        (dataset_id,),
    )

    rows = await db.run(
        db.query,
        f"SELECT * FROM {table} ORDER BY {ingest.ROW_COL} LIMIT ? OFFSET ?",
        (limit, offset),
    )

    return {
        "dataset_id": dataset_id,
        "columns": columns,
        "rows": rows,
        "total": row["row_count"],
        "offset": offset,
        "limit": limit,
    }


@router.delete("/{dataset_id}")
async def delete_dataset(dataset_id: str) -> dict[str, Any]:
    await _dataset_or_404(dataset_id)
    await db.run(ingest.drop_dataset, dataset_id)
    return {"deleted": dataset_id}
